import{_ as a,o as i,c as e,ai as n}from"./chunks/framework.Duywnu3E.js";const k=JSON.parse('{"title":"9. Настройте протокол динамической конфигурации хостов для сети в сторону HQ-CLI:","description":"","frontmatter":{},"headers":[],"relativePath":"module1/task1-9.md","filePath":"module1/task1-9.md"}'),l={name:"module1/task1-9.md"};function p(t,s,h,d,c,r){return i(),e("div",null,[...s[0]||(s[0]=[n(`<h1 id="_9-настроите-протокол-динамическои-конфигурации-хостов-для-сети-в-сторону-hq-cli" tabindex="-1">9. Настройте протокол динамической конфигурации хостов для сети в сторону HQ-CLI: <a class="header-anchor" href="#_9-настроите-протокол-динамическои-конфигурации-хостов-для-сети-в-сторону-hq-cli" aria-label="Permalink to “9. Настройте протокол динамической конфигурации хостов для сети в сторону HQ-CLI:”">​</a></h1><details class="details custom-block"><summary>Details</summary><ul><li><p>Настройте нужную подсеть</p></li><li><p>В качестве сервера DHCP выступает маршрутизатор HQ-RTR</p></li><li><p>Клиентом является машина HQ-CLI</p></li><li><p>Исключите из выдачи адрес маршрутизатора</p></li><li><p>Адрес шлюза по умолчанию – адрес маршрутизатора HQ-RTR</p></li><li><p>Адрес DNS-сервера для машины HQ-CLI – адрес сервера HQ-SRV</p></li><li><p>DNS-суффикс – au-team.irpo</p></li><li><p>Сведения о настройке протокола занесите в отчёт</p></li></ul></details><p>В рамках руководства, будем придерживаться <a href="/sa-demo-wiki/appendix/ip_table.html">этой таблицы адресации</a>, <em><strong>чего и вам советуем, если вы слепо следуете руководству и не понимаете что делаете!</strong></em></p><p>Устанавливаем DHCP-сервер на HQ-RTR.</p><div class="language-shell"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">apt-get</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dhcp-server</span></span></code></pre></div><h2 id="_9-1-конфигурация-dhcp-сервера-на-hq-rtr" tabindex="-1">9.1 Конфигурация DHCP-сервера на HQ-RTR <a class="header-anchor" href="#_9-1-конфигурация-dhcp-сервера-на-hq-rtr" aria-label="Permalink to “9.1 Конфигурация DHCP-сервера на HQ-RTR”">​</a></h2><p>Редактируем конфигурационный файл <code>/etc/dhcp/dhcpd.conf</code>. За основу можно взять пример из <code>/etc/dhcp/dhcpd.conf.sample</code>.</p><div class="language-txt line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># HQ-RTR</span></span>
<span class="line"><span># /etc/dhcp/dhcpd.conf</span></span>
<span class="line highlighted"><span>subnet 192.168.200.0 netmask 255.255.255.248 {</span></span>
<span class="line highlighted"><span>    option routers 192.168.200.1;</span></span>
<span class="line highlighted"><span>    option subnet-mask 255.255.255.248;</span></span>
<span class="line highlighted"><span>    option domain-name &quot;au-team.irpo&quot;;</span></span>
<span class="line highlighted"><span>    option domain-name-servers 192.168.100.2;</span></span>
<span class="line highlighted"><span>    range 192.168.200.2 192.168.200.6;</span></span>
<span class="line highlighted"><span>}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br></div></div><div class="info custom-block"><p class="custom-block-title custom-block-title-default">INFO</p><ul><li><code>option routers</code> — адрес шлюза по умолчанию (HQ-RTR)</li><li><code>option domain-name-servers</code> — адрес DNS-сервера (HQ-SRV)</li><li><code>option domain-name</code> — DNS-суффикс</li><li><code>range</code> — диапазон выдаваемых адресов. Адрес маршрутизатора (<code>192.168.200.1</code>) исключён из диапазона</li></ul></div><p>Перезапускаем и добавляем в автозагрузку службу DHCP.</p><div class="language-shell"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">systemctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> enable</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --now</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dhcpd</span></span></code></pre></div><h2 id="_9-2-настроика-dhcp-клиента-на-hq-cli" tabindex="-1">9.2 Настройка DHCP-клиента на HQ-CLI <a class="header-anchor" href="#_9-2-настроика-dhcp-клиента-на-hq-cli" aria-label="Permalink to “9.2 Настройка DHCP-клиента на HQ-CLI”">​</a></h2><p>На машине HQ-CLI меняем тип получения адреса с <code>static</code> на <code>dhcp</code> в конфигурации VLAN-интерфейса.</p><div class="language-txt line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># HQ-CLI</span></span>
<span class="line"><span># /etc/net/ifaces/ens18.200/options</span></span>
<span class="line highlighted"><span>BOOTPROTO=dhcp</span></span>
<span class="line highlighted"><span>TYPE=vlan</span></span>
<span class="line highlighted"><span>VID=200</span></span>
<span class="line highlighted"><span>HOST=ens18</span></span>
<span class="line highlighted"><span>CONFIG_IPV4=yes</span></span>
<span class="line highlighted"><span>DISABLED=no</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br></div></div><div class="tip custom-block"><p class="custom-block-title custom-block-title-default">TIP</p><p>Файлы <code>ipv4address</code> и <code>ipv4route</code> для интерфейса <code>ens18.200</code> на HQ-CLI больше не нужны — адрес, шлюз и DNS теперь выдаются по DHCP. Их можно удалить.</p></div><p>Перезапускаем сетевую службу.</p><div class="language-shell"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">systemctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> restart</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> network</span></span></code></pre></div><h2 id="_9-3-проверка-работоспособности" tabindex="-1">9.3 Проверка работоспособности <a class="header-anchor" href="#_9-3-проверка-работоспособности" aria-label="Permalink to “9.3 Проверка работоспособности”">​</a></h2><p>Проверяем, что HQ-CLI получил адрес по DHCP.</p><div class="language-shell"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># HQ-CLI</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ip</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> a</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> show</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ens18.200</span></span></code></pre></div><p>Если интерфейс получил адрес из диапазона <code>192.168.200.2–192.168.200.6</code> — DHCP работает корректно.</p>`,21)])])}const g=a(l,[["render",p]]);export{k as __pageData,g as default};
